cd /tmp/vally-eval-trial-uTlmtB && mkdir -p tests/CheckoutPricing.UnitTests/Pricing && cat > tests/CheckoutPricing.UnitTests/Pricing/GoldDiscountTests.cs <<'E'
using System.Reflection;
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Pricing;

public class GoldDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_00_subtotal_pays_95_00()
    {
        var checkout = typeof(ApplicationMarker).Assembly.GetExportedTypes()
            .FirstOrDefault(t => t.Name.Contains("Checkout", StringComparison.OrdinalIgnoreCase)
                              || t.Name.Contains("Pricing", StringComparison.OrdinalIgnoreCase));

        Assert.True(checkout is not null,
            "No checkout/pricing type exists in CheckoutPricing.Application; cannot calculate a payable total (expected 95.00 for Gold, 100.00 subtotal).");
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -25

